-- =============================================================================
-- Origen Salud · Programa Médico Obligatorio (PMO / PMOE) - PostgreSQL 18
-- Res. 201/2002 PMOE + Actualización Normativa 1/2002
-- =============================================================================
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- PMO (Res. 201/2002 PMOE + Actualizacion Normativa 1/2002)


DROP TABLE IF EXISTS pmo_practicas;
CREATE TABLE pmo_practicas (
  id SERIAL PRIMARY KEY,
  codigo VARCHAR(10) NOT NULL UNIQUE,
  cap_cod VARCHAR(10),
  capitulo VARCHAR(150),
  subcapitulo VARCHAR(150),
  practica TEXT NOT NULL,
  notas TEXT,
  cobertura_condicionada SMALLINT DEFAULT 0,
  revisar SMALLINT DEFAULT 0
);
CREATE INDEX idx_pmo_practicas_codigo ON pmo_practicas (codigo);

DROP TABLE IF EXISTS pmo_formulario;
CREATE TABLE pmo_formulario (
  id SERIAL PRIMARY KEY,
  atc VARCHAR(20),
  nivel SMALLINT,
  nombre VARCHAR(255) NOT NULL,
  notas TEXT,
  revisar SMALLINT DEFAULT 0
);

DROP TABLE IF EXISTS pmo_precios;
CREATE TABLE pmo_precios (
  id SERIAL PRIMARY KEY,
  principio_activo VARCHAR(150) NOT NULL,
  principio_key VARCHAR(150),
  presentacion VARCHAR(150),
  precio_ref NUMERIC(10,2),
  cobertura_40 NUMERIC(10,2),
  pagina SMALLINT,
  revisar SMALLINT DEFAULT 0
);

DROP TABLE IF EXISTS pmo_odontologia;
CREATE TABLE pmo_odontologia (
  id SERIAL PRIMARY KEY,
  codigo VARCHAR(20) NOT NULL UNIQUE,
  practica TEXT NOT NULL,
  descripcion TEXT
);

DROP TABLE IF EXISTS pmo_texto;
CREATE TABLE pmo_texto (
  id SERIAL PRIMARY KEY,
  seccion VARCHAR(50),
  numero VARCHAR(20),
  titulo TEXT,
  texto TEXT
);


-- =============================================================================
-- ÍNDICES OPTIMIZADOS (B-Tree y GIN Trigram)
-- =============================================================================
CREATE INDEX IF NOT EXISTS idx_pmo_practicas_cod ON pmo_practicas(codigo);
CREATE INDEX IF NOT EXISTS idx_pmo_practicas_cap ON pmo_practicas(cap_cod);
CREATE INDEX IF NOT EXISTS idx_pmo_practicas_trgm ON pmo_practicas USING gin (practica gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_pmo_practicas_cap_trgm ON pmo_practicas USING gin (capitulo gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_pmo_formulario_atc ON pmo_formulario(atc);
CREATE INDEX IF NOT EXISTS idx_pmo_formulario_trgm ON pmo_formulario USING gin (nombre gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_pmo_precios_act ON pmo_precios(principio_key);
CREATE INDEX IF NOT EXISTS idx_pmo_precios_trgm ON pmo_precios USING gin (principio_activo gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_pmo_odonto_cod ON pmo_odontologia(codigo);
CREATE INDEX IF NOT EXISTS idx_pmo_odonto_trgm ON pmo_odontologia USING gin (practica gin_trgm_ops);

CREATE INDEX IF NOT EXISTS idx_pmo_texto_sec ON pmo_texto(seccion, numero);
CREATE INDEX IF NOT EXISTS idx_pmo_texto_trgm ON pmo_texto USING gin (titulo gin_trgm_ops);

-- =============================================================================
-- INTEGRACIÓN CON EL SISTEMA MAESTRO: nomencladores_argentina
-- =============================================================================
-- Inserta o actualiza las prácticas PMO en la tabla maestra de nomencladores
-- para que estén disponibles inmediatamente en /v1/nomenclador y /v1/search.

    tipo_nomenclador,
    codigo,
    capitulo,
    descripcion,
    unidad_tipo,
    unidad_valor,
    gastos_valor,
    activo
)
SELECT 
    'NN_PMO' AS tipo_nomenclador,
    p.codigo,
    p.capitulo,
    p.practica,
    'GALENO' AS unidad_tipo,
    NULL AS unidad_valor,
    NULL AS gastos_valor,
    TRUE AS activo
FROM pmo_practicas p
ON CONFLICT (tipo_nomenclador, codigo) DO UPDATE SET
    capitulo = EXCLUDED.capitulo,
    descripcion = EXCLUDED.descripcion,
    activo = TRUE;

-- Inserta las prácticas odontológicas PMO en nomencladores_argentina
    tipo_nomenclador,
    codigo,
    capitulo,
    descripcion,
    unidad_tipo,
    unidad_valor,
    gastos_valor,
    activo
)
SELECT 
    'PMO_ODONTO' AS tipo_nomenclador,
    o.codigo,
    'Capítulo 06 - Odontología PMO' AS capitulo,
    o.practica,
    'MODULO' AS unidad_tipo,
    NULL AS unidad_valor,
    NULL AS gastos_valor,
    TRUE AS activo
FROM pmo_odontologia o
ON CONFLICT (tipo_nomenclador, codigo) DO UPDATE SET
    capitulo = EXCLUDED.capitulo,
    descripcion = EXCLUDED.descripcion,
    activo = TRUE;

-- =============================================================================
-- ESTADÍSTICAS Y VERIFICACIÓN
-- =============================================================================
ANALYZE pmo_practicas;
ANALYZE pmo_formulario;
ANALYZE pmo_precios;
ANALYZE pmo_odontologia;
ANALYZE pmo_texto;
ANALYZE nomencladores_argentina;

SELECT 'pmo_practicas' AS tabla, count(*) AS registros FROM pmo_practicas
UNION ALL
SELECT 'pmo_formulario', count(*) FROM pmo_formulario
UNION ALL
SELECT 'pmo_precios', count(*) FROM pmo_precios
UNION ALL
SELECT 'pmo_odontologia', count(*) FROM pmo_odontologia
UNION ALL
SELECT 'pmo_texto', count(*) FROM pmo_texto
UNION ALL
SELECT 'nomencladores_argentina (NN_PMO)', count(*) FROM nomencladores_argentina WHERE tipo_nomenclador = 'NN_PMO'
UNION ALL
SELECT 'nomencladores_argentina (PMO_ODONTO)', count(*) FROM nomencladores_argentina WHERE tipo_nomenclador = 'PMO_ODONTO';
