INSERT INTO pmo_odontologia (codigo,practica,descripcion) VALUES
('1.01','Consulta. Diagnóstico. Fichado y plan de tratamiento.','Este código incluye examen, diagnóstico y plan de tratamiento. Se considera como primera consulta y comprende la confección de la ficha odontológica.'),
('1.04','Consulta de urgencia.','Se considera consulta de urgencia a toda consulta sin turno previo, que resuelva la demanda espontánea. El beneficiario una vez resuelta la urgencia podrá consultar a su odontólogo general para iniciar el tratamiento definitivo de la patología que lo afecte. No se contempla dentro de esa consulta la realización de prácticas no cubiertas, a excepción del cementado de puentes y coronas que no requieran de restauración protética.'),
('2.01','Obturación de amalgama. Cavidad simple.',''),
('2.02','Obturación de amalgama. Cavidad compuesta o compleja.',''),
('2.04','Obturación con tornillo en conducto.','Comprende el tratamiento de los tejidos duros del diente para resolver los daños provocados por la caries dental cuando la destrucción coronaria sea mayor que los dos tercios de la distancia intercuspídea. La obturación definitiva debe incluir, en menores de 18 años, el sellado de todas las superficies no tratadas. Será reconocida una única vez por pieza tratada.'),
('2.05','Obturación resina autocurado. Cavidad simple.',''),
('2.06','Obturación resina autocurado. Cavidad compuesta o com-','pleja.'),
('2.08','Obturación resina fotocurado sector anterior.','Comprende la restauración de las piezas anteriores y vestibular de primeros premolares.'),
('2.09','Reconstrucción de ángulo en dientes anteriores.',''),
('3.01','Tratamiento endodóntico en unirradiculares.',''),
('3.02','Tratamiento endodóntico en multirradiculares.',''),
('3.05','Biopulpectomía parcial.',''),
('3.06','Necropulpectomía parcial o momificación.','En piezas que por causa técnicamente justificada no se pueda realizar el tratamiento endodóntico convencional.'),
('5.01','Tartrectomía y cepillado mecánico.','Está práctica no incluye el blanqueamiento de piezas dentarias. En pacientes mayores de 18 se cubrirá una vez por año.'),
('5.02','Consulta preventiva. Terapias fluoradas','Incluye Tartrectomía y cepillado mecánico, detección y control de la placa bacteriana, enseñanza de técnicas de higiene. Se cubrirá hasta los 18 años y hasta dos veces por año. Comprende aplicación de flúor tópico, barniz y colutorios.'),
('5.04','Consulta preventiva. Detección control de placa bacteriana,','y enseñanza de técnicas de higiene bucal. Comprende enseñanza de técnicas de cepillado, uso de elementos de higiene interdentarios, asesoramiento dietético y revelado de placa. Incluye monitoreo anual.'),
('5.05','Selladores de surcos, fosas y fisuras.','Esta práctica se reconoce hasta los 15 años en premolares y molares permanentes.'),
('5.06','Aplicación de cariostáticos en piezas dentarias permanentes.',''),
('7.01','Consultas de motivación.','Se cubrirá hasta los 15 años de edad e incluye la consulta diagnóstica, examen y plan de tratamiento. Comprende hasta tres visitas al consultorio.'),
('7.02','Mantenedor de espacio.','Comprende mantenedores de espacios fijos o removibles. Se cubrirá por única vez por pieza dentaria y en pacientes de hasta 8 años inclusive. Se incluye corona o banda y ansa de alambre de apoyo o tornillo de expansión.'),
('7.03','Reducción de luxación con inmovilización dentaria.',''),
('7.04','Tratamientos en dientes temporarios con Formocresol.','Cuando el diente tratado no esté próximo a su exfoliación. También se cubrirá en piezas permanentes con gran destrucción coronaria.'),
('7.05','Corona de acero provisoria por destrucción coronaria.','Se cubrirá en piezas temporarias con tratamiento de formocresol o gran destrucción coronaria, cuando la pieza no se encuentre dentro del período de exfoliación. En primeros molares permanentes hasta los 15 años de edad.'),
('7.06','Reimplante dentario e inmovilización por luxación total.',''),
('7.07','Protección pulpar directa.',''),
('8.01','Consulta de estudio. Sondaje, fichado, diagnóstico y pro-','nóstico.'),
('8.02','Tratamiento de gingivitis.','Comprende tartrectomía, raspaje y alisado, detección y control de placa, topicación con flúor y enseñanza de técnicas de higiene bucal. Se cubrirá anualmente.'),
('8.03','Tratamiento de enfermedad periodontal.','Comprende todos los cuadros periodontales e incluye raspaje y alisado radicular. Se cubrirá cada dos años.'),
('8.04','Desgaste selectivo o armonización aclusal.',''),
('9.01','Radiografía periapical. Técnica de cono corto o largo. Ra-','diografía Bte-Wing.'),
('9.02','Radiografía oclusal.',''),
('9.03','Radiografías dentales media seriada: de 5 a 7 películas',''),
('9.04','Radiografías dentales seriada: de 8 a 14 películas.',''),
('9.05','Pantomografía o radiografía panorámica.',''),
('9.06','Estudio cefalométrico.',''),
('10.01','Extracción dentaria.',''),
('10.02','Plástica de comunicación buco-sinusal.',''),
('10.03','Biopsia por punción o aspiración o escisión.',''),
('10.04','Alveolectomía estabilizadora.',''),
('10.05','Reimplante dentario inmediato al traumatismo con inmo-','vilización.'),
('10.06','Incisión y drenaje de absesos.',''),
('10.08','Extracción dentaria en retención mucosa.',''),
('10.09','Extracción de dientes con retención ósea.',''),
('10.10','Germectomía.',''),
('10.11','Liberación de dientes retenidos.',''),
('10.13','Tratamiento de la osteomielitis.',''),
('10.14','Extracción de cuerpo extraño.',''),
('10.15','Alveolectomía correctiva.',''),
('10.16','Frenectomía.','');
INSERT INTO pmo_texto (seccion,numero,titulo,texto) VALUES
('resolucion','','Resolución 201/2002','Ministerio de Salud SALUD PUBLICA Resolución 201/2002 Apruébase el Programa Médico Obligatorio de Emergencia (PMOE) integrado por el conjunto de prestaciones básicas esenciales garantizadas por los Agentes del Seguro de Salud comprendidos en el artículo 1º de la Ley Nº 23.660. Bs. As., 9/4/2002 VISTO las Leyes 23.660 y 23.661, los Decretos Nros. 576/ 93, 865/00, 486/02 y las Resoluciones del Ministerio de Salud Nros. 939/00, 1/01 y 45/01; y CONSIDERANDO: Que el Decreto Nº 486/02 declaró la Emergencia Sanitaria en todo el país, a los efectos de garantizar a la población argentina el acceso a los bienes y servicios básicos para la conservación de la salud de todos los habitantes de la Nación. Que en el mencionado decreto faculta al Ministerio de Salud para definir en un plazo de TREINTA (30) días, en el marco del Programa Médico Obligatorio (PMO) aprobado por Resolución Nº 939/00 del citado Ministerio y sus modificatorias, las prestaciones básicas esenciales a las que comprende la emergencia sanitaria. Que a esos fines se consideran prestaciones básicas esenciales las necesarias e imprescindibles para la preservación de la vida y la atención de las enfermedades que deben garantizar el Sistema Nacional del Seguro de Salud y el Instituto Nacional de Servicios Sociales para Jubilados y Pensionados, mientras subsista la situación de emergencia. Que de este modo el Sistema Nacional del Seguro de Salud, debe tender a garantizar la equidad, la universalidad y la solidaridad para todos sus beneficiarios. Que la caída de los recursos financieros del sector salud han motivado la ruptura de la cadena de pagos, con el consiguiente riesgo para los beneficiarios del Sistema Nacional del Seguro de Salud de no recibir las prestaciones básicas esenciales que garanticen el cuidado de la salud. Que la normativa que aprobó el Programa Médico Obligatorio y sus modificatorias, no garantiza las prestaciones básicas indispensables, porque no jerarquiza relación costo–efectividad ni la medicina basada en evidencia por lo que al dispersar el recurso económico no premia la eficiencia ni la eficacia. Que la falta de inversión en los programas de atención primaria de la salud y la prevención sobre los grupos vulnerables provocan mayores gastos en enfermedades catastróficas y mayor morbimortalidad sobre afecciones evitables. Que, de no realizar acciones concretas, la pérdida de financiamiento llevará a la eventual desaparición de Agentes del Sistema Nacional del Seguro de Salud, que aun siendo viables en esta emergencia corren riesgo cierto de desaparecer. Que la caída en la consulta médica, la falta de medidas de prevención y la no provisión de medicamentos e insumos, hacen necesario generar mecanismos para que las obras sociales garanticen las prestaciones básicas a sus beneficiarios y esto se manifieste en mejor calidad de vida. Que existe discordancia entre las prestaciones a las que se obliga a los Agentes del Sistema Nacional Seguro de Salud a través de la Resolución Nº 939/00 y los recursos humanos y materiales para sustentarla. Que en la Resolución Nº 939/00 se admite la cobertura de prácticas y procedimientos no avalados por la evidencia científica. Que debe asegurarse en una situación de emergencia sanitaria como la presente un Conjunto de Prestaciones Básicas Esenciales que permitan mantener el espíritu solidario del sistema y solucionar los problemas más frecuentes en la práctica médica. Que se deben priorizar las políticas de prevención de la enfermedad por sobre las acciones curativas basadas en las distintas características sociodemográficas que tienen cada una de las poblaciones de los Agentes del Sistema Nacional del Seguro de Salud Que asegurar la provisión de tecnología adecuada a un costo que el sistema pueda afrontar es vital, como lo indica la Declaración de Alma Ata. Que es un deber normatizar la utilización de aquellas prestaciones de alto costo que se corresponden a patologías de baja incidencia, con el objeto de garantizar una utilización racional, dado que la sobreutilización provoca un fuerte impacto económico negativo en detrimento de prácticas y procedimientos de probada efectividad clínica ante iguales circunstancias. Que en la Emergencia Sanitaria se debe garantizar el acceso a la salud de todos y en especial la protección de la salud de los grupos más vulnerables como embarazadas, niños en edad escolar, mayores de SESENTA Y CINCO 65 años y otros reglamentados por leyes especiales. Que, de acuerdo a lo establecido por el Decreto Nº 486/02 se le ha dado intervención al INSTITUTO DE SERVICIOS SOCIALES PARA JUBILADOS Y PENSIONADOS. Que dado el carácter dinámico que tiene la evolución de la ciencia médica, y la crítica situación en la que se encuentra el país, surge por tanto la necesidad de actualizar periódicamente este instrumento para lo cual la misma Resolución Nº 939/00 sentó las bases para la conformación del trabajo de la Comisión de Seguimiento Permanente del Programa Médico Obligatorio. Que para ello ha sido necesario a su vez no sólo generar consensos a través de los integrantes de la Comisión de referencia, sino también el apoyo continuo de un grupo de evaluación de tecnología a fin de brindar soporte a dicha Comisión. Que es necesario mantener coherencia conceptual entre los distintos anexos que integran el PMO, así como con las normativas generales existentes, tales como las emanadas por el Programa Nacional de Garantía de Calidad Médica. Que en el Anexo II de la Resolución Nº 939/00 y sus modificatorias se estableció un Catálogo de Prestaciones del PMO y se hace necesario explicitar sus alcances, así como también dar cuenta de una serie de prácticas establecidas como de alta complejidad, a las cuales la SUPERINTENDENCIA DE SERVICIOS DE SALUD se había comprometido a normatizar. Que debe depender la obligatoriedad de su cobertura de una correcta indicación médica, acorde a los principios establecidos en el modelo de abordaje de medicina basada en la evidencia. Que en el proceso de normatizar prácticas se arriba a conclusiones que inicialmente descartan la indicación de éstas en determinadas condiciones, lo cual no implica que existan potenciales indicaciones no consideradas en esta resolución pero pasibles de actualización a partir de la Comisión de referencia. Que este Programa Médico Obligatorio fue sometido a consideración de distintos actores del sector dentro del marco del Diálogo Argentino, en la Mesa Sectorial de Salud, donde se establecieron como objetivos generales: sostener y mejorar el sistema de salud para evitar el impacto sanitario de la crisis socioeconómica, priorizar la prevención y la atención de la salud maternoinfantil, recomponer el acceso al medicamento así como el insumo crítico para la atención médica y asegurar la continuidad de los servicios de la Seguridad Social. Que las causales de interés público precedentemente expuestas habilitan asimismo al suscripto para que, de oficio y mediante resolución fundada, suspenda legítimamente la ejecución del Programa Médico Obligatorio vigente. Que la DIRECCION GENERAL DE ASUNTOS JURIDICOS ha tomado la intervención de su competencia. Que se actúa en el marco de las atribuciones acordadas por el artículo 18 del Decreto Nº 486/02 y el artículo 12 de la Ley Nacional de Procedimientos Administrativos Nº 19.549. Por ello, EL MINISTRO DE SALUD RESUELVE Artículo 1º — Aprobar el conjunto de prestaciones básicas esenciales garantizadas por los Agentes del Seguro de Salud comprendidos en el Artículo 1º de la Ley 23.660, detalladas en los Anexos I, II, III y IV que forman parte de la presente Resolución y que en lo sucesivo se denominaran Programa Médico Obligatorio de Emergencia (PMOE). Art. 2º — Disponer que los Agentes del Seguro deberán adaptar todos sus programas de prestación y control, así como sus contratos a los efectos de garantizar el Programa Médico Obligatorio de Emergencia (PMOE) a todos sus beneficiarios. Art. 3º — Establecer que este Programa Médico Obligatorio de Emergencia (PMOE) entrará en vigencia a partir de la publicación en el Boletín Oficial. Art. 4º — Disponer que el Programa Médico Obligatorio de Emergencia (PMOE) tendrá vigencia mientras dure la Emergencia Sanitaria, debiendo la SUPERINTENDENCIA DE SERVICIOS DE SALUD conformar una Comisión de revisión del Programa Médico Obligatorio definitivo, a ser presentado para su aprobación antes del 31 de Diciembre de 2002. Art. 5º — Suspender los efectos de las Resoluciones del Ministerio de Salud Nros. 939/00; 1/01; 45/01 y todas aquellas que se opongan a la presente, mientras subsista la Emergencia Sanitaria. Art. 6º — Comuníquese, publíquese, dése a la Dirección Nacional del Registro Oficial y archívese. — Ginés M. González García.'),
('anexo1','1','Cobertura',''),
('anexo1','1.1','Atención Primaria de la Salud:','Se reafirma el principio de que este Programa Médico Obligatorio está basado en los principios de la atención primaria de la salud, entendiendo a la misma no sólo como la cobertura para el primer nivel de atención, sino y fundamentalmente como una estrategia de organización de los servicios sanitarios. Por tanto se sostienen los principios de privilegiar la preservación de la salud antes que las acciones curativas, y por tanto reforzar los programas de prevención. Brindar una cobertura integral, es decir un abordaje biopsicosocial de los problemas de salud. Asegurar un mecanismo integrado de atención en los distintos niveles de prevención primaria, secundaria y terciaria. Proveer de cuidados continuos a los beneficiarios, privilegiando la atención a partir de un médico de familia que sea el responsable de los cuidados de los beneficiarios, y donde los mismos tengan el derecho a conocer el nombre de su médico, así como los demás proveedores de servicios obligándose a conocer y acompañar en forma integral a los pacientes en el cuidado de su salud la recuperación de la misma y la rehabilitación. Programas de Prevención Primaria y Secundaria: Se deberán acordar en colaboración con la autoridad jurisdiccional. En todos los casos será obligación de los Agentes del Seguro la entrega del listado de personas bajo programa, el cual deberá ser elevado en forma trimestral a la Superintendencia de Servicios de Salud en conjunto con la información requerida en la Resolución 650/97 ANSSAL y modificatorias. En todos los casos para que un programa de prevención sea reconocido como tal los Agentes del Seguro deberán especificar objetivos, metas, recursos humanos, recursos materiales, guías de atención, mecanismos de evaluación y resultados esperados, los mencionados programas deberán presentarse en la Superintendencia de Servicios de Salud. Los Agentes del Seguro de Salud, deberán adaptar los programas de prevención a sus características sociodemográficas particulares, además de los otros planes que consideren procedentes por las características del Agente .'),
('anexo1','1.1.1','Plan Materno Infantil: Se dará cobertura durante el emba-','razo y el parto a partir del momento del diagnóstico y hasta el primer mes luego del nacimiento.'),
('anexo1','1.1.2','Atención del recién nacido hasta cumplir un año de edad.','Todo con cobertura al 100% tanto en internación como en ambulatorio y exceptuado del pago de todo tipo de coseguros para las atenciones y medicaciones específicas. Esta cobertura comprende: a) Embarazo y parto: consultas, estudios de diagnóstico exclusivamente relacionados con el embarazo, el parto y puerperio, ya que otro tipo de estudios tendrá la cobertura que rige al resto de este PMO; psicoprofilaxis obstétrica, medicamentos exclusivamente relacionados con el embarazo y el parto con cobertura al 100%. b) Infantil: Será obligatoria la realización perinatológica de los estudios para detección de la fenilcetonuria, del hipotiroidismo congénito y enfermedad fibroquística en el recién nacido. Deberán cubrirse las consultas de seguimiento y control, inmunizaciones del período, cobertura del 100% de la medicación requerida para el primer año de vida siempre que ésta figure en el listado de medicamentos esenciales. c) A fin de estimular la lactancia materna no se cubrirán las leches maternizadas o de otro tipo, salvo expresa indicación médica, con evaluación de la auditoría médica.'),
('anexo1','1.1.3','Programas de prevención de cánceres femeninos: en espe-','cial de cáncer de mama y cuello uterino, diagnóstico y tratamiento de todas las afecciones malignas. Siempre con la cobertura de las medicaciones que figuren en los protocolos del Programa Nacional de Garantía de Calidad de la Atención Médica. Se excluyen de la cobertura todo tipo de tratamientos y/o protocolos de carácter experimental o en fase de prueba.'),
('anexo1','1.1.4','Odontología preventiva: campos de prevención, fluoración','y campañas de educación para la salud bucal.'),
('anexo1','2','Atención Secundaria:','Los Agentes del Seguro de Salud se encuentran obligados a brindar exclusivamente las especialidades reconocidas por la autoridad sanitaria nacional.'),
('anexo1','2.1','Especialidades:','• Anatomía Patológica • Diagnóstico por imágenes: Radiología, tomografía computada, resonancia magnética • Anestesiología • Cardiología y ecografía. • Cirugía cardiovascular • Endocrinología • Cirugía de cabeza y cuello • Infectología • Cirugía general • Fisiatría (medicina física y rehabilitación) • Cirugía infantil • Cirugía plástica reparadora • Gastroenterología • Cirugía de tórax • Geriatría • Clínica médica • Ginecología • Dermatología • Hematología • Hemoterapia • Oftalmología • Medicina familiar y General • Oncología • Medicina nuclear: diagnóstico y tratamiento • Ortopedia y traumatología • Nefrología • Otorrinolaringología • Neonatología • Pediatría • Neumonología • Psiquiatría • Neurología • Reumatología • Nutrición • Terapia intensiva • Obstetricia • Urología'),
('anexo1','2.2','Las prestaciones a brindar son:','Se asegura la consulta en consultorio e internación. Se asegura la consulta de urgencia y emergencia en domicilio. En los mayores de 65 años que no puedan movilizarse, se asegura la consulta programada en domicilio con un coseguro de $10 por cada visita. En todo otro grupo etario donde sea el paciente esté imposibilitado de desplazarse quedará a discreción de la auditoría del Agente del Seguro la provisión de Atención programada en domicilio.'),
('anexo1','2.3','Prácticas y estudios complementarios ambulatorios, diag-','nósticos y terapéuticos: todas las prácticas diagnósticas y terapéuticas detalladas en el anexo II de la presente Resolución, con iderando el material descartable y los medios de contraste como parte de la prestación que se realiza.'),
('anexo1','3','Internación:','Se asegura el 100% de cobertura en la internación en cualquiera de sus modalidades (institucional, hospital de día o domiciliaria). Todas las prestaciones y prácticas que se detallan en el anexo II se encuentran incluidas dentro de la cobertura. La cobertura se extiende sin límite de tiempo, a excepción de lo contemplado en el capítulo que corresponde a salud mental. 4 Salud mental:'),
('anexo1','4.1','Se incluyen todas aquellas actividades de fortalecimiento y','desarrollo de comportamientos y hábitos de vida saludables como forma de promoción de la salud en general y de la salud mental en particular.'),
('anexo1','4.2','Actividades específicas que tienden a prevenir comporta-','mientos que puedan generar trastornos y malestares psíquicos en temas específicos como la depresión, suicidio, adicciones, violencia, violencia familiar, maltrato infantil. Los agentes del seguro propiciarán las prácticas de promoción de salud mental mediante el desarrollo de actividades acordes a las modalidades que consideren pertinentes para su población beneficiaria.'),
('anexo1','4.3','Prestaciones cubiertas: atención ambulatoria hasta 30 visitas','por año calendario, no pudiendo exceder la cantidad de 4 consultas mensuales. Esto incluye las modalidades de entrevista psiquiátrica, psicológica, psicopedagogía, psicoterapia individual, psicoterapia grupal, psicoterapia de familia y de pareja, psicodiagnóstico.'),
('anexo1','4.4','Internación: se cubrirán patologías agudas en las modalida-','des institucional u hospital de día. Hasta 30 días por año calendario.'),
('anexo1','5','Rehabilitación:','Se incluyen todas las prácticas kinesiológicas y fonoaudiológicas que se detallan en el Anexo II de la presente Resolución. Los Agentes del Seguro de Salud darán cobertura ambulatoria para rehabilitación motriz, psicomotriz, readaptación ortopédica y rehabilitación sensorial. Kinesioterapia: hasta 25 sesiones por beneficiario por año calendario Fonoaudiología: hasta 25 sesiones por beneficiario por año calendario Estimulación temprana: en los términos que se define en el Anexo II de la presente Resolución'),
('anexo1','6','Odontología:',''),
('anexo1','6.1','Se asegura la cobertura por parte de los Agentes del Seguro','de Salud, de las siguientes prácticas:'),
('anexo1','6.2','El monto de coseguros a pagar será de hasta $ 4 para niños de','hasta 15 años, y para mayores de 65 años. Co-seguro de hasta $ 7 para aquellos beneficiarios que tienen entre 16 y 64 años.'),
('anexo1','6.3','Los coseguros serán pagados en donde el Agente del Seguro','de Salud lo determine.'),
('anexo1','7','Medicamentos',''),
('anexo1','7.1','Se asegura la cobertura de los medicamentos en ambulatorio','que figuran en el Anexo III de la presente con un 40% de cobertura, conforme al precio de referencia que se explicita en el anexo IV, y en las formas farmacéuticas allí indicadas.'),
('anexo1','7.2','La cobertura será del 100% en internados.',''),
('anexo1','7.3','Tendrán cobertura al 100% por parte del Agente del Seguro:','Eritropoyetina en el tratamiento de la Insuficiencia Renal Crónica. Medicamentos oncológicos según protocolos nacionales aprobados por la autoridad de aplicación.'),
('anexo1','7.4','La cobertura de medicación no oncológica, de uso de proto-','colos oncológicos, tendrá la misma cobertura que la medicación ambulatoria, a excepción del ondasetrón en el tratamiento de vómitos agudos inducidos por drogas altamente emetizantes.(cisplatino, carboplatino, ciclofosfamida, ifosfamida, dactinomicina D, dacarbazina, doxorrubicina, idarrubicina, epirrubicina, estreptozotocina, citarabina).'),
('anexo1','7.5','Tendrán cobertura del 100% con financiamiento del Fondo','Solidario de Redistribución los Programas Especiales de la Administración de Programas Especiales (APE) y los programas comprendidos en leyes de protección de grupos vulnerables. Sin perjuicio de las normas establecidas en esta Resolución sobre la cobertura en medicamentos, las mismas no podrán introducir limitaciones sobre tratamientos en curso al momento de su puesta en vigencia. Se mantiene a cargo de los Agentes del Seguro la cobertura de medicamentos establecida en otras normativas vigentes: • Res. 301/99 MsyAS. Cobertura de insulina (100%), antidiabéticos orales (70%) y tirillas reactivas (400 anuales). Para pacientes diabéticos insulinodependientes lábiles participantes en programas específicos de prevención secundaria se duplicará la provisión de tirillas para medición de glucemia (autocontrol). • Res. 791/99 MSyAS. Cobertura del 100% del mestinón 60 mg. para el tratamiento de la Miastenia Gravis'),
('anexo1','7.6','Todos los prestadores que brinden servicios a los Agentes','del Seguro deberán recetar medicamentos por su nombre genérico, y se aplicarán los mecanismos de sustitución y precios de referencia para establecer la cobertura a cargo del Agente del Seguro.'),
('anexo1','8','Otras coberturas',''),
('anexo1','8.1','El cuidado paliativo es la asistencia activa y total de los','pacientes por un equipo multidisciplinario, cuando la expectativa de vida del paciente no supera el lapso de 6 meses, por no responder al tratamiento curativo que le fue impuesto. Los objetivos aquí serán aliviar el dolor, los síntomas y el abordaje psicosocial del paciente. La cobertura estará dada en función del marco general que marca el PMO, es decir que los Agentes del Seguro se encuentran obligados a brindar las prestaciones que se mencionan en los Anexos II y III con un 100% de cobertura.'),
('anexo1','8.2','Hemodiálisis y Diálisis Peritoneal Continua Ambulatoria.','La cobertura será del 100% siendo requisito indispensable la inscripción de los pacientes en el INCUCAI dentro de los primeros 30 días de iniciado el tratamiento. La auditoría Médica establecerá la modalidad a ser cubierta según la necesidad individual de cada beneficiario.'),
('anexo1','8.3.1','Se asegura la cobertura de otoamplífonos al 100% en niños','de hasta 15 años a fin de garantizar un adecuado nivel de audición que les permita sostener una educación que maximice las potencialidades personales de cada beneficiario.'),
('anexo1','8.3.2','Con igual criterio que el anterior se asegura la cobertura de','anteojos con lentes estándar, en un 100% a niños de hasta 15 años.'),
('anexo1','8.3.3','Prótesis y órtesis: La cobertura será del 100% en prótesis','e implantes de colocación interna permanente y del 50% en órtesis y prótesis externas, no reconociéndose las prótesis denominadas miogénicas o bioeléctricas. El monto máximo a erogar por el Agente del Seguro será el de la menor cotización en plaza. Las indicaciones médicas se efectuarán por nombre genérico, sin aceptar sugerencias de marcas, proveedor u especificaciones técnicas que orienten la prescripción encubierta de determinado producto. El Agente del Seguro deberá proveer las prótesis nacionales según indicación, sólo se admitirán prótesis importadas cuando no exista similar nacional. La responsabilidad del Agente del Seguro se extingue al momento de la provisión de la prótesis nacional.'),
('anexo1','8.3.4','Los traslados son parte de la prestación que se realiza. La','Auditoría Médica podrá autorizar otros traslados de acuerdo a la necesidad de los beneficiarios.'),
('anexo1','9','Coseguros',''),
('anexo1','9.1','Las prestaciones cubiertas por los Agentes del Seguro no','abonarán ningún tipo de coseguro por fuera de los descriptos en la presente Resolución.'),
('anexo1','9.2','Están exceptuados del pago de todo tipo de coseguros:','La mujer embarazada desde el momento del diagnóstico hasta 30 días después del parto, en todas las prestaciones inherentes al estado del embarazo, parto y puerperio de acuerdo a normativa. Las complicaciones y enfermedades derivadas del embarazo parto y puerperio hasta su resolución. El niño hasta cumplido el año de edad de acuerdo a normativa. Los pacientes oncológicos de acuerdo a normativa. Los programas preventivos. Se establece un monto de hasta $ 4 en concepto de coseguro para todo tipo de consultas médicas en ambulatorio, siendo facultad del Agente del Seguro el cobro del mismo y la modalidad operativa para su percepción. Se unifican en un solo valor de hasta $5 los montos para estudios de alta y baja complejidad.'),
('anexo1','10','El Programa Médico Obligatorio debe cumplir con el Progra-','ma Nacional de Garantía de Calidad de la Atención Médica.'),
('anexo1','11','El Programa Médico Obligatorio debe cumplir con el Progra-','ma de Vigilancia de la Salud y Control de Enfermedades (VIGIA) en el ámbito de la Seguridad Social (según marca el Decreto 865/ 2000) a fin de garantizar la salud de la población en especial en emergencias sociales como la presente en dónde el número de personas vulnerables a enfermedades transmisibles y no transmisibles puede aumentar.');
INSERT INTO nomencladores_argentina (
INSERT INTO nomencladores_argentina (
